/* Community chat, round 38, run after part 270. `community_chat_settings` gets who may START a conversation beyond everyone, the team only or off: members from a points level (dm_policy level, dm_min_level) or after some days in the community (dm_policy days, dm_min_days), whether members may write to the team (dm_to_staff), whether the community shows a Chat tab (chat_tab) and which channel it opens (main_space_id, null for the first). `community_spaces` gets a channel's points level to post (post_min_level, 0 for none; the team only is post_role as before) and its pinned message (pinned_message_id, pinned_at, pinned_by). `community_chat_automations` are messages a community sends by itself: on a join, a level reached, some days after joining, a paid membership started or cancelled, or once to members or a part of them (a level, a tier, joined lately), now or at a time; into each member's messages or into a channel, from a member of the team. `community_chat_automation_deliveries` is one row per automation and member (unique, so nobody gets one twice; a channel message is the one row with no member), each sent by the server in small batches and written once however often it is retried. RLS on both new tables and nothing granted to members: only the server reads and writes them. No rows change. Safe to run again. */
ALTER TABLE public.community_chat_settings ADD COLUMN IF NOT EXISTS dm_min_level integer NOT NULL DEFAULT 2, ADD COLUMN IF NOT EXISTS dm_min_days integer NOT NULL DEFAULT 7, ADD COLUMN IF NOT EXISTS dm_to_staff boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS chat_tab boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS main_space_id uuid REFERENCES public.community_spaces(id) ON DELETE SET NULL;
ALTER TABLE public.community_chat_settings DROP CONSTRAINT IF EXISTS community_chat_settings_dm_policy, ADD CONSTRAINT community_chat_settings_dm_policy CHECK (dm_policy IN ('everyone', 'level', 'days', 'staff', 'off'));
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_chat_settings_dm_min_level') THEN ALTER TABLE public.community_chat_settings ADD CONSTRAINT community_chat_settings_dm_min_level CHECK (dm_min_level BETWEEN 1 AND 100); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_chat_settings_dm_min_days') THEN ALTER TABLE public.community_chat_settings ADD CONSTRAINT community_chat_settings_dm_min_days CHECK (dm_min_days BETWEEN 1 AND 365); END IF; END $do$;
ALTER TABLE public.community_spaces ADD COLUMN IF NOT EXISTS post_min_level integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS pinned_message_id uuid REFERENCES public.community_messages(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS pinned_at timestamptz, ADD COLUMN IF NOT EXISTS pinned_by uuid REFERENCES auth.users(id) ON DELETE SET NULL;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_spaces_post_min_level_range') THEN ALTER TABLE public.community_spaces ADD CONSTRAINT community_spaces_post_min_level_range CHECK (post_min_level BETWEEN 0 AND 100) NOT VALID; END IF; END $do$;
CREATE TABLE IF NOT EXISTS public.community_chat_automations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, name text NOT NULL, trigger text NOT NULL, trigger_level integer, trigger_days integer, segment jsonb NOT NULL DEFAULT '{}'::jsonb, target text NOT NULL DEFAULT 'dm', space_id uuid REFERENCES public.community_spaces(id) ON DELETE SET NULL, sender_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, body text NOT NULL, status text NOT NULL DEFAULT 'active', send_at timestamptz, cursor_at timestamptz, cursor_user uuid, fanned_out_at timestamptz, sent_count integer NOT NULL DEFAULT 0, failed_count integer NOT NULL DEFAULT 0, last_sent_at timestamptz, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_chat_automations_trigger CHECK (trigger IN ('join', 'level', 'days', 'paid_start', 'paid_cancel', 'broadcast')), CONSTRAINT community_chat_automations_target CHECK (target IN ('dm', 'channel')), CONSTRAINT community_chat_automations_status CHECK (status IN ('active', 'paused', 'scheduled', 'sending', 'done')), CONSTRAINT community_chat_automations_name_len CHECK (char_length(name) BETWEEN 1 AND 80), CONSTRAINT community_chat_automations_body_len CHECK (char_length(body) BETWEEN 1 AND 4000), CONSTRAINT community_chat_automations_level CHECK (trigger_level IS NULL OR trigger_level BETWEEN 2 AND 100), CONSTRAINT community_chat_automations_days CHECK (trigger_days IS NULL OR trigger_days BETWEEN 1 AND 365), CONSTRAINT community_chat_automations_segment_object CHECK (jsonb_typeof(segment) = 'object'), CONSTRAINT community_chat_automations_counts CHECK (sent_count >= 0 AND failed_count >= 0));
CREATE INDEX IF NOT EXISTS community_chat_automations_community_idx ON public.community_chat_automations (community_id, created_at DESC);
CREATE INDEX IF NOT EXISTS community_chat_automations_due_idx ON public.community_chat_automations (trigger, status, send_at);
CREATE TABLE IF NOT EXISTS public.community_chat_automation_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), automation_id uuid NOT NULL REFERENCES public.community_chat_automations(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, due_at timestamptz NOT NULL DEFAULT now(), claimed_at timestamptz, sent_at timestamptz, message_id uuid, error text, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_chat_automation_deliveries_status CHECK (status IN ('pending', 'sending', 'sent', 'failed', 'skipped')), CONSTRAINT community_chat_automation_deliveries_attempts CHECK (attempts >= 0), CONSTRAINT community_chat_automation_deliveries_error_len CHECK (error IS NULL OR char_length(error) <= 300), CONSTRAINT community_chat_automation_deliveries_once UNIQUE (automation_id, user_id));
CREATE UNIQUE INDEX IF NOT EXISTS community_chat_automation_deliveries_channel_once ON public.community_chat_automation_deliveries (automation_id) WHERE user_id IS NULL;
CREATE INDEX IF NOT EXISTS community_chat_automation_deliveries_waiting_idx ON public.community_chat_automation_deliveries (status, due_at) WHERE status IN ('pending', 'sending');
CREATE INDEX IF NOT EXISTS community_chat_automation_deliveries_automation_idx ON public.community_chat_automation_deliveries (automation_id, status);
ALTER TABLE public.community_chat_automations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_chat_automation_deliveries ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_chat_automations, public.community_chat_automation_deliveries FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_chat_automations, public.community_chat_automation_deliveries TO service_role;
notify pgrst, 'reload schema';
